      "arFull": "وَابْتَلُوا الْیَتٰمٰی حَتّٰۤی اِذَا بَلَغُوا النِّكَاحَ ۚ فَاِنْ اٰنَسْتُمْ مِّنْهُمْ رُشْدًا فَادْفَعُوْۤا اِلَیْهِمْ اَمْوَالَهُمْ ۚ وَلَا تَاْكُلُوْهَاۤ اِسْرَافًا وَّبِدَارًا اَنْ یَّكْبَرُوْا ؕ وَمَنْ كَانَ غَنِیًّا فَلْیَسْتَعْفِفْ ۚ وَمَنْ كَانَ فَقِیْرًا فَلْیَاْكُلْ بِالْمَعْرُوْفِ ؕ فَاِذَا دَفَعْتُمْ اِلَیْهِمْ اَمْوَالَهُمْ فَاَشْهِدُوْا عَلَیْهِمْ ؕ وَكَفٰی بِاللّٰهِ حَسِیْبًا ۟",
      "ur": "اور یتیموں کو ان کے بالﻎ ہو جانے تک سدھارتے اور آزماتے رہو پھر اگر ان میں تم ہوشیاری اور حسن تدبیر پاؤ تو انہیں ان کے مال سونﭗ دو اور ان کے بڑے ہو جانے کے ڈر سے ان کے مالوں کو جلدی جلدی فضول خرچیوں میں تباه نہ کر دو، مال داروں کو چاہئے کہ (ان کے مال سے) بچتے رہیں، ہاں مسکین محتاج ہو تو دستور کے مطابق واجبی طور سے کھالے، پھر جب انہیں ان کے مال سونپو تو گواه بنا لو، دراصل حساب لینے واﻻ اللہ تعالیٰ ہی کافی ہے۔[1]",
