      "arFull": "وَالّٰتِیْ یَاْتِیْنَ الْفَاحِشَةَ مِنْ نِّسَآىِٕكُمْ فَاسْتَشْهِدُوْا عَلَیْهِنَّ اَرْبَعَةً مِّنْكُمْ ۚ فَاِنْ شَهِدُوْا فَاَمْسِكُوْهُنَّ فِی الْبُیُوْتِ حَتّٰی یَتَوَفّٰهُنَّ الْمَوْتُ اَوْ یَجْعَلَ اللّٰهُ لَهُنَّ سَبِیْلًا ۟",
