      "en": "Those who commit immorality [i.e., unlawful sexual intercourse] of your women - bring against them four [witnesses] from among you. And if they testify,[169] confine them [i.e., the guilty women] to houses until death takes them or Allāh ordains for them [another] way.[170]",
