      "number": 19,
      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا یَحِلُّ لَكُمْ اَنْ تَرِثُوا النِّسَآءَ كَرْهًا ؕ وَلَا تَعْضُلُوْهُنَّ لِتَذْهَبُوْا بِبَعْضِ مَاۤ اٰتَیْتُمُوْهُنَّ اِلَّاۤ اَنْ یَّاْتِیْنَ بِفَاحِشَةٍ مُّبَیِّنَةٍ ۚ وَعَاشِرُوْهُنَّ بِالْمَعْرُوْفِ ۚ فَاِنْ كَرِهْتُمُوْهُنَّ فَعَسٰۤی اَنْ تَكْرَهُوْا شَیْـًٔا وَّیَجْعَلَ اللّٰهُ فِیْهِ خَیْرًا كَثِیْرًا ۟",
