      "arFull": "وَاِنْ اَرَدْتُّمُ اسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ ۙ وَّاٰتَیْتُمْ اِحْدٰىهُنَّ قِنْطَارًا فَلَا تَاْخُذُوْا مِنْهُ شَیْـًٔا ؕ اَتَاْخُذُوْنَهٗ بُهْتَانًا وَّاِثْمًا مُّبِیْنًا ۟",
      "ur": "اور اگر تم ایک بیوی کی جگہ دوسری بیوی کرنا ہی چاہو اور ان میں سے کسی کو تم نے خزانہ کا خزانہ دے رکھا ہو، تو بھی اس میں سے کچھ نہ لو[1] کیا تم اسے ناحق اور کھلا گناه ہوتے ہوئے بھی لے لو گے ۔",
