      "arFull": "وَّالْمُحْصَنٰتُ مِنَ النِّسَآءِ اِلَّا مَا مَلَكَتْ اَیْمَانُكُمْ ۚ كِتٰبَ اللّٰهِ عَلَیْكُمْ ۚ وَاُحِلَّ لَكُمْ مَّا وَرَآءَ ذٰلِكُمْ اَنْ تَبْتَغُوْا بِاَمْوَالِكُمْ مُّحْصِنِیْنَ غَیْرَ مُسٰفِحِیْنَ ؕ فَمَا اسْتَمْتَعْتُمْ بِهٖ مِنْهُنَّ فَاٰتُوْهُنَّ اُجُوْرَهُنَّ فَرِیْضَةً ؕ وَلَا جُنَاحَ عَلَیْكُمْ فِیْمَا تَرٰضَیْتُمْ بِهٖ مِنْ بَعْدِ الْفَرِیْضَةِ ؕ اِنَّ اللّٰهَ كَانَ عَلِیْمًا حَكِیْمًا ۟",
      "ur": "اور (حرام کی گئیں) شوہر والی عورتیں مگر وه جو تمہاری ملکیت میں آجائیں[1] ، اللہ تعالیٰ نے یہ احکام تم پر فرض کر دیئے ہیں، اور ان عورتوں کے سوا اور عورتیں تمہارے لئے حلال کی گئیں کہ اپنے مال کے مہر سے تم ان سے نکاح کرنا چاہو برے کام سے بچنے کے لئے نہ کہ شہوت رانی کرنے کے لئے[2]، اس لئے جن سے تم فائده اٹھاؤ انہیں ان کا مقرر کیا ہوا مہر دے دو[3]، اور مہر مقرر ہو جانے کے بعد تم آپس کی رضامندی سے جو طے کرلو اس میں تم پر کوئی گناه نہیں[4]، بے شک اللہ تعالیٰ علم واﻻ حکمت واﻻ ہے۔",
      "en": "And [also prohibited to you are all] married women except those your right hands possess.[177] [This is] the decree of Allāh upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation[178] as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allāh is ever Knowing and Wise.",
