      "arFull": "وَاللّٰهُ یُرِیْدُ اَنْ یَّتُوْبَ عَلَیْكُمْ ۫ وَیُرِیْدُ الَّذِیْنَ یَتَّبِعُوْنَ الشَّهَوٰتِ اَنْ تَمِیْلُوْا مَیْلًا عَظِیْمًا ۟",
