      "arFull": "اِنْ تَجْتَنِبُوْا كَبَآىِٕرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَیِّاٰتِكُمْ وَنُدْخِلْكُمْ مُّدْخَلًا كَرِیْمًا ۟",
      "ur": "اگر تم ان بڑے گناہوں سے بچتے رہوگے جن سے تم کو منع کیا جاتا ہے[1] تو ہم تمہارے چھوٹے گناه دور کر دیں گے اور عزت وبزرگی کی جگہ داخل کریں گے۔",
