      "ur": "اوراس چیز کی آرزو نہ کرو جس کے باعﺚ اللہ تعالیٰ نے تم میں سے بعض کو بعض پر بزرگی دی ہے، مردوں کا اس میں سے حصہ ہے جو انہوں نے کمایا اور عورتوں کے لئے ان میں سے حصہ ہے جو انہوں نے کمایا، اور اللہ تعالیٰ سے اس کا فضل مانگو[1] ، یقیناً اللہ ہر چیز کا جاننے واﻻ ہے۔",
      "en": "And do not wish for that by which Allāh has made some of you exceed others. For men is a share of what they have earned, and for women is a share of[180] what they have earned. And ask Allāh of His bounty. Indeed Allāh is ever, of all things, Knowing.",
