      "arFull": "وَلِكُلٍّ جَعَلْنَا مَوَالِیَ مِمَّا تَرَكَ الْوَالِدٰنِ وَالْاَقْرَبُوْنَ ؕ وَالَّذِیْنَ عَقَدَتْ اَیْمَانُكُمْ فَاٰتُوْهُمْ نَصِیْبَهُمْ ؕ اِنَّ اللّٰهَ كَانَ عَلٰی كُلِّ شَیْءٍ شَهِیْدًا ۟۠",
