      "number": 40,
      "arFull": "اِنَّ اللّٰهَ لَا یَظْلِمُ مِثْقَالَ ذَرَّةٍ ۚ وَاِنْ تَكُ حَسَنَةً یُّضٰعِفْهَا وَیُؤْتِ مِنْ لَّدُنْهُ اَجْرًا عَظِیْمًا ۟",
      "ur": "بے شک اللہ تعالیٰ ایک ذره برابر ﻇلم نہیں کرتا اور اگر نیکی ہو تو اسے دوگنی کر دیتا ہے اور خاص اپنے پاس سے بہت بڑا ﺛواب دیتا ہے۔",
