      "arFull": "یَوْمَىِٕذٍ یَّوَدُّ الَّذِیْنَ كَفَرُوْا وَعَصَوُا الرَّسُوْلَ لَوْ تُسَوّٰی بِهِمُ الْاَرْضُ ؕ وَلَا یَكْتُمُوْنَ اللّٰهَ حَدِیْثًا ۟۠",
