      "arFull": "اِنَّ اللّٰهَ لَا یَغْفِرُ اَنْ یُّشْرَكَ بِهٖ وَیَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ یَّشَآءُ ۚ وَمَنْ یُّشْرِكْ بِاللّٰهِ فَقَدِ افْتَرٰۤی اِثْمًا عَظِیْمًا ۟",
      "ur": "یقیناً اللہ تعالیٰ اپنے ساتھ شریک کئے جانے کو نہیں بخشتا اور اس کے سوا جسے چاہے بخش دیتا ہے[1] اور جو اللہ تعالیٰ کے ساتھ شریک مقرر کرے اس نے بہت بڑا گناه اور بہتان باندھا۔[2]",
