      "arFull": "اَلَمْ تَرَ اِلَی الَّذِیْنَ یُزَكُّوْنَ اَنْفُسَهُمْ ؕ بَلِ اللّٰهُ یُزَكِّیْ مَنْ یَّشَآءُ وَلَا یُظْلَمُوْنَ فَتِیْلًا ۟",
