      "arFull": "اَلَمْ تَرَ اِلَی الَّذِیْنَ اُوْتُوْا نَصِیْبًا مِّنَ الْكِتٰبِ یُؤْمِنُوْنَ بِالْجِبْتِ وَالطَّاغُوْتِ وَیَقُوْلُوْنَ لِلَّذِیْنَ كَفَرُوْا هٰۤؤُلَآءِ اَهْدٰی مِنَ الَّذِیْنَ اٰمَنُوْا سَبِیْلًا ۟",
