      "arFull": "فَمِنْهُمْ مَّنْ اٰمَنَ بِهٖ وَمِنْهُمْ مَّنْ صَدَّ عَنْهُ ؕ وَكَفٰی بِجَهَنَّمَ سَعِیْرًا ۟",
