      "arFull": "اِنَّ الَّذِیْنَ كَفَرُوْا بِاٰیٰتِنَا سَوْفَ نُصْلِیْهِمْ نَارًا ؕ كُلَّمَا نَضِجَتْ جُلُوْدُهُمْ بَدَّلْنٰهُمْ جُلُوْدًا غَیْرَهَا لِیَذُوْقُوا الْعَذَابَ ؕ اِنَّ اللّٰهَ كَانَ عَزِیْزًا حَكِیْمًا ۟",
