      "number": 58,
      "arFull": "اِنَّ اللّٰهَ یَاْمُرُكُمْ اَنْ تُؤَدُّوا الْاَمٰنٰتِ اِلٰۤی اَهْلِهَا ۙ وَاِذَا حَكَمْتُمْ بَیْنَ النَّاسِ اَنْ تَحْكُمُوْا بِالْعَدْلِ ؕ اِنَّ اللّٰهَ نِعِمَّا یَعِظُكُمْ بِهٖ ؕ اِنَّ اللّٰهَ كَانَ سَمِیْعًا بَصِیْرًا ۟",
