      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اَطِیْعُوا اللّٰهَ وَاَطِیْعُوا الرَّسُوْلَ وَاُولِی الْاَمْرِ مِنْكُمْ ۚ فَاِنْ تَنَازَعْتُمْ فِیْ شَیْءٍ فَرُدُّوْهُ اِلَی اللّٰهِ وَالرَّسُوْلِ اِنْ كُنْتُمْ تُؤْمِنُوْنَ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ ؕ ذٰلِكَ خَیْرٌ وَّاَحْسَنُ تَاْوِیْلًا ۟۠",
