      "arFull": "فَلَا وَرَبِّكَ لَا یُؤْمِنُوْنَ حَتّٰی یُحَكِّمُوْكَ فِیْمَا شَجَرَ بَیْنَهُمْ ثُمَّ لَا یَجِدُوْا فِیْۤ اَنْفُسِهِمْ حَرَجًا مِّمَّا قَضَیْتَ وَیُسَلِّمُوْا تَسْلِیْمًا ۟",
