      "arFull": "وَمَنْ یُّطِعِ اللّٰهَ وَالرَّسُوْلَ فَاُولٰٓىِٕكَ مَعَ الَّذِیْنَ اَنْعَمَ اللّٰهُ عَلَیْهِمْ مِّنَ النَّبِیّٖنَ وَالصِّدِّیْقِیْنَ وَالشُّهَدَآءِ وَالصّٰلِحِیْنَ ۚ وَحَسُنَ اُولٰٓىِٕكَ رَفِیْقًا ۟ؕ",
