      "arFull": "وَمَا لَكُمْ لَا تُقَاتِلُوْنَ فِیْ سَبِیْلِ اللّٰهِ وَالْمُسْتَضْعَفِیْنَ مِنَ الرِّجَالِ وَالنِّسَآءِ وَالْوِلْدَانِ الَّذِیْنَ یَقُوْلُوْنَ رَبَّنَاۤ اَخْرِجْنَا مِنْ هٰذِهِ الْقَرْیَةِ الظَّالِمِ اَهْلُهَا ۚ وَاجْعَلْ لَّنَا مِنْ لَّدُنْكَ وَلِیًّا ۙۚ وَّاجْعَلْ لَّنَا مِنْ لَّدُنْكَ نَصِیْرًا ۟ؕ",
