      "arFull": "اَيْنَمَا تَكُوْنُوْا یُدْرِكْكُّمُ الْمَوْتُ وَلَوْ كُنْتُمْ فِیْ بُرُوْجٍ مُّشَیَّدَةٍ ؕ وَاِنْ تُصِبْهُمْ حَسَنَةٌ یَّقُوْلُوْا هٰذِهٖ مِنْ عِنْدِ اللّٰهِ ۚ وَاِنْ تُصِبْهُمْ سَیِّئَةٌ یَّقُوْلُوْا هٰذِهٖ مِنْ عِنْدِكَ ؕ قُلْ كُلٌّ مِّنْ عِنْدِ اللّٰهِ ؕ فَمَالِ هٰۤؤُلَآءِ الْقَوْمِ لَا یَكَادُوْنَ یَفْقَهُوْنَ حَدِیْثًا ۟",
