      "number": 83,
      "arFull": "وَاِذَا جَآءَهُمْ اَمْرٌ مِّنَ الْاَمْنِ اَوِ الْخَوْفِ اَذَاعُوْا بِهٖ ؕ وَلَوْ رَدُّوْهُ اِلَی الرَّسُوْلِ وَاِلٰۤی اُولِی الْاَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِیْنَ یَسْتَنْۢبِطُوْنَهٗ مِنْهُمْ ؕ وَلَوْلَا فَضْلُ اللّٰهِ عَلَیْكُمْ وَرَحْمَتُهٗ لَاتَّبَعْتُمُ الشَّیْطٰنَ اِلَّا قَلِیْلًا ۟",
      "ur": "جہاں انہیں کوئی خبر امن کی یا خوف کی ملی انہوں نے اسے مشہور کرنا شروع کر دیا، حاﻻنکہ اگر یہ لوگ اسے رسول (صلی اللہ علیہ وسلم) کے اور اپنے میں سے ایسی باتوں کی تہہ تک پہنچنے والوں کے حوالے کر دیتے، تو اس کی حقیقت وه لوگ معلوم کر لیتے جو نتیجہ اخذ کرتے ہیں[1] اور اگر اللہ تعالیٰ کا فضل اور اس کی رحمت تم پر نہ ہوتی تو معدودے چند کے علاوه تم سب شیطان کے پیروکار بن جاتے۔",
      "en": "And when there comes to them something [i.e., information] about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allāh upon you and His mercy, you would have followed Satan, except for a few.",
