      "arFull": "وَدُّوْا لَوْ تَكْفُرُوْنَ كَمَا كَفَرُوْا فَتَكُوْنُوْنَ سَوَآءً فَلَا تَتَّخِذُوْا مِنْهُمْ اَوْلِیَآءَ حَتّٰی یُهَاجِرُوْا فِیْ سَبِیْلِ اللّٰهِ ؕ فَاِنْ تَوَلَّوْا فَخُذُوْهُمْ وَاقْتُلُوْهُمْ حَیْثُ وَجَدْتُّمُوْهُمْ ۪ وَلَا تَتَّخِذُوْا مِنْهُمْ وَلِیًّا وَّلَا نَصِیْرًا ۟ۙ",
      "ur": "ان کی تو چاہت ہے کہ جس طرح کے کافر وه ہیں تو بھی ان کی طرح کفر کرنے لگو اور پھر سب یکساں ہو جاؤ، پس جب تک یہ اسلام کی خاطر وطن نہ چھوڑیں ان میں سے کسی کو حقیقی دوست نہ بناؤ[1] ، پھر اگر یہ منھ پھیر لیں تو انہیں پکڑو[2] اور قتل کرو جہاں بھی یہ ہاتھ لگ جائیں[3]، خبردار! ان میں سے کسی کو اپنا رفیق اور مددگار نہ سمجھ بیٹھنا۔",
