      "arFull": "لَا یَسْتَوِی الْقٰعِدُوْنَ مِنَ الْمُؤْمِنِیْنَ غَیْرُ اُولِی الضَّرَرِ وَالْمُجٰهِدُوْنَ فِیْ سَبِیْلِ اللّٰهِ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ ؕ فَضَّلَ اللّٰهُ الْمُجٰهِدِیْنَ بِاَمْوَالِهِمْ وَاَنْفُسِهِمْ عَلَی الْقٰعِدِیْنَ دَرَجَةً ؕ وَكُلًّا وَّعَدَ اللّٰهُ الْحُسْنٰی ؕ وَفَضَّلَ اللّٰهُ الْمُجٰهِدِیْنَ عَلَی الْقٰعِدِیْنَ اَجْرًا عَظِیْمًا ۟ۙ",
