      "arFull": "وَمَنْ یُّهَاجِرْ فِیْ سَبِیْلِ اللّٰهِ یَجِدْ فِی الْاَرْضِ مُرٰغَمًا كَثِیْرًا وَّسَعَةً ؕ وَمَنْ یَّخْرُجْ مِنْ بَیْتِهٖ مُهَاجِرًا اِلَی اللّٰهِ وَرَسُوْلِهٖ ثُمَّ یُدْرِكْهُ الْمَوْتُ فَقَدْ وَقَعَ اَجْرُهٗ عَلَی اللّٰهِ ؕ وَكَانَ اللّٰهُ غَفُوْرًا رَّحِیْمًا ۟۠",
