      "arFull": "وَلَا تَهِنُوْا فِی ابْتِغَآءِ الْقَوْمِ ؕ اِنْ تَكُوْنُوْا تَاْلَمُوْنَ فَاِنَّهُمْ یَاْلَمُوْنَ كَمَا تَاْلَمُوْنَ ۚ وَتَرْجُوْنَ مِنَ اللّٰهِ مَا لَا یَرْجُوْنَ ؕ وَكَانَ اللّٰهُ عَلِیْمًا حَكِیْمًا ۟۠",
