      "arFull": "وَلَا تُجَادِلْ عَنِ الَّذِیْنَ یَخْتَانُوْنَ اَنْفُسَهُمْ ؕ اِنَّ اللّٰهَ لَا یُحِبُّ مَنْ كَانَ خَوَّانًا اَثِیْمًا ۟ۚۙ",
