      "arFull": "وَمَنْ یَّكْسِبْ خَطِیْٓئَةً اَوْ اِثْمًا ثُمَّ یَرْمِ بِهٖ بَرِیْٓـًٔا فَقَدِ احْتَمَلَ بُهْتَانًا وَّاِثْمًا مُّبِیْنًا ۟۠",
      "ur": "اور جو شخص کوئی گناه یا خطا کر کے کسی بے گناه کے ذمے تھوپ دے، اس نے بہت بڑا بہتان اٹھایا اور کھلا گناه کیا۔[1]",
