      "number": 115,
      "arFull": "وَمَنْ یُّشَاقِقِ الرَّسُوْلَ مِنْ بَعْدِ مَا تَبَیَّنَ لَهُ الْهُدٰی وَیَتَّبِعْ غَیْرَ سَبِیْلِ الْمُؤْمِنِیْنَ نُوَلِّهٖ مَا تَوَلّٰی وَنُصْلِهٖ جَهَنَّمَ ؕ وَسَآءَتْ مَصِیْرًا ۟۠",
