      "arFull": "وَاِنْ یَّتَفَرَّقَا یُغْنِ اللّٰهُ كُلًّا مِّنْ سَعَتِهٖ ؕ وَكَانَ اللّٰهُ وَاسِعًا حَكِیْمًا ۟",
