      "arFull": "وَقَدْ نَزَّلَ عَلَیْكُمْ فِی الْكِتٰبِ اَنْ اِذَا سَمِعْتُمْ اٰیٰتِ اللّٰهِ یُكْفَرُ بِهَا وَیُسْتَهْزَاُ بِهَا فَلَا تَقْعُدُوْا مَعَهُمْ حَتّٰی یَخُوْضُوْا فِیْ حَدِیْثٍ غَیْرِهٖۤ ۖؗ اِنَّكُمْ اِذًا مِّثْلُهُمْ ؕ اِنَّ اللّٰهَ جَامِعُ الْمُنٰفِقِیْنَ وَالْكٰفِرِیْنَ فِیْ جَهَنَّمَ جَمِیْعَا ۟ۙ",
