      "ur": "(یہ سزا تھی) بہ سبب ان کی عہد شکنی کے اور احکام الٰہی کے ساتھ کفر کرنے کے اور اللہ کے نبیوں کو ناحق قتل کر ڈالنے کے[1] ، اور اس سبب سے کہ یوں کہتے ہیں کہ ہمارے دلوں پر غلاف ہے۔ حاﻻنکہ دراصل ان کے کفر کی وجہ سے ان کے دلوں پر اللہ تعالیٰ نے مہر لگا دی ہے، اس لئے یہ قدر قلیل ہی ایمان ﻻتے ہیں۔",
