      "arFull": "وَاِنْ مِّنْ اَهْلِ الْكِتٰبِ اِلَّا لَیُؤْمِنَنَّ بِهٖ قَبْلَ مَوْتِهٖ ۚ وَیَوْمَ الْقِیٰمَةِ یَكُوْنُ عَلَیْهِمْ شَهِیْدًا ۟ۚ",
