      "arFull": "لٰكِنِ الرّٰسِخُوْنَ فِی الْعِلْمِ مِنْهُمْ وَالْمُؤْمِنُوْنَ یُؤْمِنُوْنَ بِمَاۤ اُنْزِلَ اِلَیْكَ وَمَاۤ اُنْزِلَ مِنْ قَبْلِكَ وَالْمُقِیْمِیْنَ الصَّلٰوةَ وَالْمُؤْتُوْنَ الزَّكٰوةَ وَالْمُؤْمِنُوْنَ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ ؕ اُولٰٓىِٕكَ سَنُؤْتِیْهِمْ اَجْرًا عَظِیْمًا ۟۠",
