      "arFull": "یَسْتَفْتُوْنَكَ ؕ قُلِ اللّٰهُ یُفْتِیْكُمْ فِی الْكَلٰلَةِ ؕ اِنِ امْرُؤٌا هَلَكَ لَیْسَ لَهٗ وَلَدٌ وَّلَهٗۤ اُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ یَرِثُهَاۤ اِنْ لَّمْ یَكُنْ لَّهَا وَلَدٌ ؕ فَاِنْ كَانَتَا اثْنَتَیْنِ فَلَهُمَا الثُّلُثٰنِ مِمَّا تَرَكَ ؕ وَاِنْ كَانُوْۤا اِخْوَةً رِّجَالًا وَّنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ الْاُنْثَیَیْنِ ؕ یُبَیِّنُ اللّٰهُ لَكُمْ اَنْ تَضِلُّوْا ؕ وَاللّٰهُ بِكُلِّ شَیْءٍ عَلِیْمٌ ۟۠",
      "ur": "آپ سے فتویٰ پوچھتے ہیں، آپ کہہ دیجیئے کہ اللہ تعالیٰ (خود) تمہیں کلالہ کے بارے میں فتویٰ دیتا ہے۔ اگر کوئی شخص مر جائے جس کی اوﻻد نہ ہو اور ایک بہن ہو تو اس کے لئے چھوڑے ہوئے مال کا آدھا حصہ ہے[1] اور وه بھائی اس بہن کا وارث ہوگا اگر اس کے اوﻻد نہ ہو[2]۔ پس اگر بہنیں دو ہوں تو انہیں کل چھوڑے ہوئے کا دو تہائی ملے گا[3]۔ اور اگر کئی شخص اس ناطے کے ہیں مرد بھی اور عورتیں بھی تو مرد کے لئے حصہ ہے مثل دو عورتوں کے[4]، اللہ تعالیٰ تمہارے لئے بیان فرما رہا ہے کہ ایسا نہ ہو کہ تم بہک جاؤ اور اللہ تعالیٰ ہر چیز سے واقف ہے۔",
      "en": "They request from you a [legal] ruling. Say, \"Allāh gives you a ruling concerning one having neither descendants nor ascendants [as heirs].\" If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two thirds of what he left. If there are both brothers and sisters, the male will have the share of two females.[238] Allāh makes clear to you [His law], lest you go astray. And Allāh is Knowing of all things.",
